package com.pixilife.android;import android.Manifest;import android.app.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.location.*;import android.os.*;import android.widget.*;import java.io.*;import java.net.*;import org.json.*;
public class NearbyActivity extends Activity {private LinearLayout list;private Spinner type;@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(25,25,25,25);r.setBackgroundColor(Color.rgb(7,11,17));type=new Spinner(this);type.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"restaurante","farmacia","cafetería","supermercado","combustible"}));r.addView(type);Button find=new Button(this);find.setText("Buscar lugares reales");find.setOnClickListener(v->find());r.addView(find);ScrollView s=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);s.addView(list);r.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);}
 private void find(){list.removeAllViews();if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){add("Falta ubicación");return;}LocationManager lm=getSystemService(LocationManager.class);Location p=null;for(String x:lm.getProviders(true)){try{Location z=lm.getLastKnownLocation(x);if(z!=null&&(p==null||z.getTime()>p.getTime()))p=z;}catch(Exception ignored){}}if(p==null){add("Ubicación todavía no disponible");return;}final Location here=p;String[] tags={"restaurant","pharmacy","cafe","supermarket","fuel"};String tag=tags[type.getSelectedItemPosition()];add("Consultando OpenStreetMap…");new Thread(()->{try{String q="[out:json][timeout:20];nwr[\"amenity\"=\""+tag+"\"](around:5000,"+here.getLatitude()+","+here.getLongitude()+");out center 20;";URL u=new URL("https://overpass-api.de/api/interpreter?data="+URLEncoder.encode(q,"UTF-8"));BufferedReader b=new BufferedReader(new InputStreamReader(u.openStream()));StringBuilder s=new StringBuilder();String l;while((l=b.readLine())!=null)s.append(l);JSONArray a=new JSONObject(s.toString()).getJSONArray("elements");runOnUiThread(()->{list.removeAllViews();for(int i=0;i<a.length();i++){JSONObject e=a.optJSONObject(i),tagsO=e.optJSONObject("tags");if(tagsO==null)continue;double la=e.has("lat")?e.optDouble("lat"):e.optJSONObject("center").optDouble("lat"),lo=e.has("lon")?e.optDouble("lon"):e.optJSONObject("center").optDouble("lon");float[] d=new float[1];Location.distanceBetween(here.getLatitude(),here.getLongitude(),la,lo,d);add(tagsO.optString("name","Sin nombre")+" · "+Math.round(d[0])+" m\n"+tagsO.optString("addr:street","Dirección no publicada"));}});}catch(Exception e){runOnUiThread(()->{list.removeAllViews();add("Error de lugares: "+e.getMessage());});}}).start();}
 private void add(String x){TextView t=new TextView(this);t.setText(x);t.setTextColor(Color.WHITE);t.setTextSize(16);t.setPadding(8,12,8,12);list.addView(t);}}
